-- Run once in Supabase Dashboard > SQL Editor. Create the administrator in Authentication > Users.
create extension if not exists pgcrypto;
create table public.events (id uuid primary key default gen_random_uuid(), title text not null, event_date date not null, location text not null default '', active boolean not null default true, eligibility_url text, privacy_purpose text not null default '헌혈행사 예약 및 운영, 연락 안내', privacy_retention text not null default '행사 종료 후 3개월', privacy_disposal text not null default '보관기간 종료 후 파기', booking_start time, booking_end time, slot_interval_minutes integer not null default 30 check (slot_interval_minutes between 5 and 240), default_slot_capacity integer not null default 5 check (default_slot_capacity > 0), unavailable_ranges jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table public.time_slots (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, slot_time time not null, capacity integer not null default 5 check (capacity > 0), enabled boolean not null default true, created_at timestamptz not null default now(), unique(event_id,slot_time));
create table public.reservations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), slot_id uuid not null references public.time_slots(id), name text not null, phone varchar(20) not null, pin varchar(4) not null check (pin ~ '^[0-9]{4}$'), eligibility_checked boolean not null default false, privacy_agreed boolean not null default true, privacy_agreed_at timestamptz not null default now(), reservation_status text not null default 'reserved' check(reservation_status in ('reserved','checked_in','no_show','cancelled')), donation_status text not null default 'pending' check(donation_status in ('pending','completed','ineligible')), checked_in_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index one_active_reservation_per_phone on public.reservations(event_id,phone) where reservation_status <> 'cancelled';
create table public.walk_ins (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), name text not null, phone varchar(20) not null, donation_status text not null check(donation_status in ('completed','ineligible')), created_at timestamptz not null default now());
create table public.pin_reset_requests (id uuid primary key default gen_random_uuid(), reservation_id uuid not null references public.reservations(id), name text not null, phone varchar(20) not null, status text not null default 'pending' check(status in ('pending','processed')), created_at timestamptz not null default now(), processed_at timestamptz);
create table public.contact_settings (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, label text not null, phone varchar(20) not null default '', display_order integer not null default 1, unique(event_id,display_order));
alter table public.events enable row level security; alter table public.time_slots enable row level security; alter table public.reservations enable row level security; alter table public.walk_ins enable row level security; alter table public.pin_reset_requests enable row level security; alter table public.contact_settings enable row level security;
create policy "admin event" on public.events for all to authenticated using(true) with check(true); create policy "admin slots" on public.time_slots for all to authenticated using(true) with check(true); create policy "admin reservations" on public.reservations for all to authenticated using(true) with check(true); create policy "admin walkins" on public.walk_ins for all to authenticated using(true) with check(true); create policy "admin pin requests" on public.pin_reset_requests for all to authenticated using(true) with check(true); create policy "admin contacts" on public.contact_settings for all to authenticated using(true) with check(true);
create or replace function public.public_booking_data() returns table(event jsonb, slots jsonb, contacts jsonb) language sql security definer set search_path=public as $$select to_jsonb(e),coalesce((select jsonb_agg(to_jsonb(x) order by x.slot_time) from (select s.*,count(r.id)::int as booked from time_slots s left join reservations r on r.slot_id=s.id and r.reservation_status <> 'cancelled' where s.event_id=e.id group by s.id)x),'[]'),coalesce((select jsonb_agg(to_jsonb(c) order by c.display_order) from contact_settings c where c.event_id=e.id),'[]') from events e where e.active=true order by e.event_date desc limit 1$$;
create or replace function public.create_reservation(p_event_id uuid,p_slot_id uuid,p_name text,p_phone text,p_pin text,p_eligibility_checked boolean) returns jsonb language plpgsql security definer set search_path=public as $$declare r reservations; s time_slots; n int; begin if p_name='' or p_phone !~ '^[0-9]{9,11}$' or p_pin !~ '^[0-9]{4}$' then return jsonb_build_object('ok',false,'message','입력 정보를 확인해주세요.');end if; select * into s from time_slots where id=p_slot_id and event_id=p_event_id and enabled for update; if not found then return jsonb_build_object('ok',false,'message','선택한 시간을 사용할 수 없습니다.');end if; select count(*) into n from reservations where slot_id=p_slot_id and reservation_status<>'cancelled';if n>=s.capacity then return jsonb_build_object('ok',false,'message','선택하신 시간의 예약이 마감되었습니다. 다른 시간을 선택해주세요.');end if; if exists(select 1 from reservations where event_id=p_event_id and phone=p_phone and reservation_status<>'cancelled') then return jsonb_build_object('ok',false,'message','이미 예약된 전화번호입니다.');end if; insert into reservations(event_id,slot_id,name,phone,pin,eligibility_checked) values(p_event_id,p_slot_id,p_name,p_phone,p_pin,p_eligibility_checked) returning * into r; return jsonb_build_object('ok',true,'reservation',jsonb_build_object('id',r.id,'name',r.name,'pin',r.pin,'slot_time',s.slot_time,'event_date',(select event_date from events where id=p_event_id),'location',(select location from events where id=p_event_id)));exception when unique_violation then return jsonb_build_object('ok',false,'message','이미 예약된 전화번호입니다.');end$$;
create or replace function public.find_reservation(p_name text,p_phone text,p_pin text) returns jsonb language plpgsql security definer set search_path=public as $$declare r reservations; begin select * into r from reservations where name=p_name and phone=p_phone and pin=p_pin and reservation_status<>'cancelled' order by created_at desc limit 1;if not found then return jsonb_build_object('ok',false);end if;return jsonb_build_object('ok',true,'reservation',jsonb_build_object('id',r.id,'name',r.name,'slot_time',(select slot_time from time_slots where id=r.slot_id),'event_date',(select event_date from events where id=r.event_id),'location',(select location from events where id=r.event_id)),'slots',(select coalesce(jsonb_agg(to_jsonb(x) order by x.slot_time),'[]') from(select s.*,count(x.id)::int booked from time_slots s left join reservations x on x.slot_id=s.id and x.reservation_status<>'cancelled' where s.event_id=r.event_id group by s.id)x));end$$;
create or replace function public.change_reservation_slot(p_reservation_id uuid,p_pin text,p_slot_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r reservations;s time_slots;n int;begin select * into r from reservations where id=p_reservation_id and pin=p_pin and reservation_status<>'cancelled' for update;if not found then return jsonb_build_object('ok',false,'message','예약정보를 확인해주세요.');end if;select * into s from time_slots where id=p_slot_id and event_id=r.event_id and enabled for update;if not found then return jsonb_build_object('ok',false,'message','선택한 시간을 사용할 수 없습니다.');end if;select count(*) into n from reservations where slot_id=s.id and reservation_status<>'cancelled' and id<>r.id;if n>=s.capacity then return jsonb_build_object('ok',false,'message','선택하신 시간의 예약이 마감되었습니다. 다른 시간을 선택해주세요.');end if;update reservations set slot_id=s.id,updated_at=now() where id=r.id returning * into r;return jsonb_build_object('ok',true,'reservation',jsonb_build_object('id',r.id,'name',r.name,'slot_time',s.slot_time,'event_date',(select event_date from events where id=r.event_id),'location',(select location from events where id=r.event_id)));end$$;
create or replace function public.cancel_reservation(p_reservation_id uuid,p_pin text) returns jsonb language plpgsql security definer set search_path=public as $$begin update reservations set reservation_status='cancelled',updated_at=now() where id=p_reservation_id and pin=p_pin and reservation_status<>'cancelled';return jsonb_build_object('ok',found);end$$;
create or replace function public.create_pin_request(p_name text,p_phone text) returns jsonb language plpgsql security definer set search_path=public as $$declare r reservations;begin select * into r from reservations where name=p_name and phone=p_phone and reservation_status<>'cancelled' order by created_at desc limit 1;if not found then return jsonb_build_object('ok',false);end if;insert into pin_reset_requests(reservation_id,name,phone) values(r.id,r.name,r.phone);return jsonb_build_object('ok',true);end$$;
create or replace function public.admin_dashboard() returns table(reserved int,capacity int,checked_in int,no_show int,completed int,ineligible int,walkins int,slots jsonb) language sql security definer set search_path=public as $$select count(r.id)filter(where r.reservation_status<>'cancelled')::int,coalesce(sum(s.capacity),0)::int,count(r.id)filter(where r.reservation_status='checked_in')::int,count(r.id)filter(where r.reservation_status='no_show')::int,count(r.id)filter(where r.donation_status='completed')::int,count(r.id)filter(where r.donation_status='ineligible')::int,(select count(*)::int from walk_ins w where w.event_id=e.id),coalesce(jsonb_agg(jsonb_build_object('id',s.id,'slot_time',s.slot_time,'capacity',s.capacity,'booked',(select count(*) from reservations z where z.slot_id=s.id and z.reservation_status<>'cancelled'),'checked_in',(select count(*) from reservations z where z.slot_id=s.id and z.reservation_status='checked_in'),'no_show',(select count(*) from reservations z where z.slot_id=s.id and z.reservation_status='no_show'),'completed',(select count(*) from reservations z where z.slot_id=s.id and z.donation_status='completed')) order by s.slot_time),'[]') from events e left join time_slots s on s.event_id=e.id left join reservations r on r.event_id=e.id where e.active=true group by e.id$$;
grant execute on function public.public_booking_data(),public.create_reservation(uuid,uuid,text,text,text,boolean),public.find_reservation(text,text,text),public.change_reservation_slot(uuid,text,uuid),public.cancel_reservation(uuid,text),public.create_pin_request(text,text),public.admin_dashboard() to anon,authenticated;
insert into events(title,event_date,location,eligibility_url) values('순천향대학교 부천병원 헌혈행사',current_date,'','https://lumpy-azimuth-7eb.notion.site/3bbe4a07fa58801aa4a1ed1578a947ac?source=copy_link');
insert into time_slots(event_id,slot_time) select id,t from events cross join unnest(array['10:00'::time,'10:30','11:00','11:30','12:00','12:30']) t;
insert into contact_settings(event_id,label,phone,display_order) select id,'혈액원 담당자','',1 from events; insert into contact_settings(event_id,label,phone,display_order) select id,'수혈관리실 담당자','',2 from events;
create or replace function public.generate_time_slots(p_event_id uuid,p_start time,p_end time,p_interval integer,p_capacity integer,p_unavailable_ranges jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare slot_at time:=p_start; allowed boolean; created_count int:=0;begin if auth.role() <> 'authenticated' then raise exception '관리자 인증이 필요합니다'; end if;if p_end<=p_start or p_interval<5 or p_capacity<1 then return jsonb_build_object('ok',false,'message','예약 시간 설정을 확인해주세요.'); end if;perform 1 from events where id=p_event_id for update;if not found then return jsonb_build_object('ok',false,'message','행사 정보를 찾을 수 없습니다.'); end if;update events set booking_start=p_start,booking_end=p_end,slot_interval_minutes=p_interval,default_slot_capacity=p_capacity,unavailable_ranges=p_unavailable_ranges where id=p_event_id;update time_slots s set enabled=false where s.event_id=p_event_id and not exists(select 1 from reservations r where r.slot_id=s.id and r.reservation_status<>'cancelled');while slot_at < p_end loop allowed:=not exists(select 1 from jsonb_to_recordset(p_unavailable_ranges) as b(start time,finish time) where slot_at>=b.start and slot_at<b.finish);if allowed then insert into time_slots(event_id,slot_time,capacity,enabled) values(p_event_id,slot_at,p_capacity,true) on conflict(event_id,slot_time) do update set capacity=excluded.capacity,enabled=true;created_count:=created_count+1;end if;slot_at:=slot_at+(p_interval||' minutes')::interval;end loop;return jsonb_build_object('ok',true,'created',created_count);end $$;
grant execute on function public.generate_time_slots(uuid,time,time,integer,integer,jsonb) to authenticated;
